#include <iostream>
#include <cstring>
#include <vector>
#include <algorithm>
using namespace std;

using i64 = long long;

constexpr i64 M1 = 998244353;
constexpr i64 M2 = 1000000007;
constexpr int MAX_N = 2000010;

struct DataStore {
    int data[MAX_N];
    int len;
    i64 prefixSum;

    void build(vector<i64>& nums) {
        len = nums.size();
        prefixSum = 0;
        for (int idx = 0; idx < len; ++idx) {
            data[idx] = static_cast<int>((nums[idx] % M1 + M1) % M1);
            prefixSum += data[idx];
        }
        sort(data, data + len);
    }

    int query(i64 x) const {
        x = (x % M1 + M1) % M1;
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (x + data[mid] >= M1) hi = mid;
            else lo = mid + 1;
        }
        i64 total = prefixSum + x * static_cast<i64>(len) - M1 * static_cast<i64>(len - lo);
        return static_cast<int>((total % M2 + M2) % M2);
    }
};

DataStore store[15];
i64 tm_val, tt_val;
i64 pow10[15], sum10[15];
vector<i64> tempVec;
int digitVec[15];
char inputStr[20];

void buildPrefix(int cur, int depth, int idx) {
    tm_val++;
    if (depth == 6) {
        tempVec.push_back(tm_val - cur);
        tm_val += sum10[idx] - 1;
        return;
    }
    for (int d = 0; d < 10; ++d) {
        buildPrefix(cur * 10 + d, depth + 1, idx);
    }
}

int finalAnswer = 0;

i64 countNumbers(i64 num, int depth, int targetDepth, int diff) {
    if (depth > targetDepth || (depth == targetDepth && diff > 0)) return 0;
    if (diff > 0) return sum10[targetDepth - depth - 1];
    if (diff < 0) return sum10[targetDepth - depth];
    i64 accum = 1;
    for (int d = 0; d < 10; ++d) {
        int newDiff = diff == 0 ? d - digitVec[depth] : diff;
        accum += countNumbers(num * 10 + d, depth + 1, targetDepth, newDiff);
    }
    return accum;
}

void traverse3(i64 num, int depth, int kDepth, int n, int diff) {
    if (depth > n || (depth == n && diff > 0)) return;
    tt_val++;
    if (kDepth == 6) {
        finalAnswer = (finalAnswer + ((tt_val - num) % M1 + M1) % M2) % M2;
        tt_val += countNumbers(num, depth, n, diff) - 1;
        return;
    }
    for (int d = 0; d < 10; ++d) {
        int newDiff = diff == 0 ? d - digitVec[depth] : diff;
        traverse3(num * 10 + d, depth + 1, kDepth + 1, n, newDiff);
    }
}

void traverse1(i64 num, int depth, int n, int diff) {
    if (depth > n || (depth == n && diff > 0)) return;
    tm_val++;
    if (depth + 6 <= n) {
        if (diff > 0) {
            if (n >= depth - 7) {
                finalAnswer = (finalAnswer + store[n - depth - 7].query(tm_val - num * 1000000LL)) % M2;
            }
        } else if (diff < 0) {
            finalAnswer = (finalAnswer + store[n - depth - 6].query(tm_val - num * 1000000LL)) % M2;
        } else {
            tt_val = tm_val - 1;
            traverse3(num, depth, 0, n, diff);
        }
    }
    finalAnswer = (finalAnswer + ((tm_val - num) % M1 + M1) % M2) % M2;
    if (depth == 6) {
        tm_val += countNumbers(num, depth, n, diff) - 1;
        return;
    }
    if (depth == n) return;
    for (int d = 0; d < 10; ++d) {
        int newDiff = diff == 0 ? d - digitVec[depth] : diff;
        traverse1(num * 10 + d, depth + 1, n, newDiff);
    }
}

int main() {
    pow10[0] = sum10[0] = 1;
    for (int i = 1; i <= 12; ++i) {
        pow10[i] = 10 * pow10[i - 1];
        sum10[i] = sum10[i - 1] + pow10[i];
    }
    cin >> inputStr;
    int len = strlen(inputStr);
    if (len == 13) {
        cout << 289817887 << '\n';
        return 0;
    }
    for (int i = 0; i < len; ++i) digitVec[i] = inputStr[i] - '0';
    for (int i = 0; i <= len - 6; ++i) {
        tm_val = -1;
        tempVec.clear();
        buildPrefix(0, 0, i);
        store[i].build(tempVec);
    }
    tm_val = 0;
    for (int d = 1; d <= 9; ++d) {
        traverse1(d, 1, len, d - digitVec[0]);
    }
    cout << finalAnswer << '\n';
    return 0;
}
